/* Хорошо — темный текст на светлом фоне */
.good-text {
  color: oklch(0.21 0.006 285);   /* тёмно-серый */
  background: oklch(0.98 0.001 285); /* светло-серый фон */
  /* Контраст ~13:1 — проходит AA и AAA */
}

/* Плохо — светло-серый на белом */
.bad-text {
  color: oklch(0.70 0.01 285);    /* слишком светло-серый */
  background: white;
  /* Контраст ~1.5:1 — не проходит даже A */
}

/* Погранично */
.borderline {
  color: oklch(0.45 0.01 285);    /* средне-серый */
  background: white;
  /* Контраст ~5.5:1 — проходит AA для обычного текста */
}

.alert--error {
  border-left: 4px solid var(--color-error);
  background: color-mix(in oklch, var(--color-error), white 92%);
  color: var(--color-text);
}

.alert__icon {
  /* Иконка ошибки — дополнительный индикатор */
}

/* Плохо — убирает outline для всех, включая клавиатуру */
input:focus {
  outline: none;
}

/* Хорошо — показывает outline только при навигации клавиатурой */
input:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* При фокусе мышкой — незаметный, при клавиатуре — заметный */
input:focus:not(:focus-visible) {
  outline: none;
}

.btn {
  /* Базовые стили */
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  border: 2px solid transparent;
}

/* Фокус для клавиатуры */
.btn:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px color-mix(in oklch, var(--color-primary), white 50%);
}

/* Фокус внутри компонента */
.c-card:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--color-primary), white 40%);
}

.skip-link {
  position: absolute;
  top: -100px;  /* Скрыто за пределами экрана */
  left: 0;
  background: var(--color-primary);
  color: white;
  padding: var(--space-sm) var(--space-md);
  z-index: 1000;
  text-decoration: none;
  border-radius: 0 0 var(--radius-md) 0;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;  /* Появляется при фокусе клавиатурой */
}

// app.js — фокус-ловушка для модалки
function trapFocus(element) {
  const focusableElements = element.querySelectorAll(
    'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
  );
  const firstElement = focusableElements[0];
  const lastElement = focusableElements[focusableElements.length - 1];

  element.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;

    if (e.shiftKey) {
      // Shift+Tab — переход назад
      if (document.activeElement === firstElement) {
        e.preventDefault();
        lastElement.focus();
      }
    } else {
      // Tab — переход вперёд
      if (document.activeElement === lastElement) {
        e.preventDefault();
        firstElement.focus();
      }
    }
  });

  // ESC закрывает модалку
  element.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeModal(element);
    }
  });
}

function openModal(modal) {
  modal.classList.add('is-open');
  modal.setAttribute('aria-modal', 'true');
  document.body.style.overflow = 'hidden';

  // Переместить фокус в модалку
  const firstFocusable = modal.querySelector('button, [href], input, select, textarea');
  if (firstFocusable) firstFocusable.focus();

  trapFocus(modal);
}

function closeModal(modal) {
  modal.classList.remove('is-open');
  modal.setAttribute('aria-modal', 'false');
  document.body.style.overflow = '';

  // Вернуть фокус на элемент, который открыл модалку
  const trigger = document.querySelector('[aria-controls="' + modal.id + '"]');
  if (trigger) trigger.focus();
}

/* Базовые анимации */
.btn {
  transition: transform 0.2s, background 0.2s;
}

.btn:hover {
  transform: translateY(-2px);
}

/* Для пользователей с preferring reduced motion — убираем анимации */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Конкретные компоненты — более точный контроль */
@media (prefers-reduced-motion: reduce) {
  .carousel {
    animation: none;
    transition: none;
  }

  .modal {
    transform: none;
    opacity: 1;
    visibility: visible;
  }

  .loading-spinner {
    animation: none;
  }
}

const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

if (prefersReducedMotion.matches) {
  // Отключить JS-анимации, карусели, параллакс
  disableAnimations();
}

prefersReducedMotion.addEventListener('change', (e) => {
  if (e.matches) {
    disableAnimations();
  } else {
    enableAnimations();
  }
});

.c-card {
  /* Вместо padding-left/right */
  padding-inline-start: var(--space-md);
  padding-inline-end: var(--space-md);
  padding-block-start: var(--space-lg);
  padding-block-end: var(--space-lg);

  /* Вместо margin-left/right */
  margin-inline-start: auto;

  /* Вместо border-left */
  border-inline-start: 4px solid var(--color-primary);

  /* Вместо text-align */
  text-align: start;

  direction: ltr;  /* или rtl, или inherit */
}

.c-nav__list {
  display: flex;
  gap: var(--space-md);
  padding-inline-start: 0;  /* Вместо padding-left: 0 */
  list-style: none;
}

.c-nav__link {
  padding-inline-start: var(--space-sm);  /* Вместо padding-left */
  padding-inline-end: var(--space-sm);    /* Вместо padding-right */
}

.c-nav__link::before {
  content: '';
  margin-inline-end: var(--space-xs);  /* Вместо margin-right */
  display: inline-block;
  width: 4px;
  height: 4px;
  background: var(--color-primary);
  border-radius: 50%;
}

/* RTL вариант — через [dir="rtl"] */
[dir="rtl"] .c-nav__link::before {
  margin-inline-end: 0;
  margin-inline-start: var(--space-xs);
}

/* Горизонтальный текст (по умолчанию) */
.writing-mode-horizontal {
  writing-mode: horizontal-tb;
}

/* Вертикальный текст, справа налево (японский традиционный) */
.writing-mode-vertical-rl {
  writing-mode: vertical-rl;
}

/* Вертикальный текст, слева направо */
.writing-mode-vertical-lr {
  writing-mode: vertical-lr;
}

/* Плохо — фиксированные пиксели не масштабируются хорошо */
.bad-text {
  font-size: 16px;
  line-height: 24px;
  padding: 20px;
}

/* Хорошо — rem, em, % масштабируются с настройками браузера */
.good-text {
  font-size: 1rem;           /* = 16px по умолчанию, масштабируется */
  line-height: 1.6;          /* без единиц — пропорционально */
  padding: 1rem;             /* масштабируется с текстом */
  max-width: 60ch;           /* символы — оптимальная длина строки */
}

.c-card {
  /* Мини- и максимальные размеры позволяют контейнеру расти с текстом */
  min-width: 200px;
  max-width: 100%;
  width: 100%;

  /* padding в rem — масштабируется */
  padding: 1.5rem;

  /* overflow — не скрывает текст при увеличении */
  overflow: visible;
}

img {
  max-width: 100%;
  height: auto;
  /* Изображение не выйдет за границы контейнера при зуме */
}

.c-form__label {
  display: block;
  margin-block-end: var(--space-xs);
  font-size: var(--fs-sm);
  font-weight: 600;
  color: var(--color-text);
}

.c-form__input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: var(--fs-base);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-bg);
  color: var(--color-text);

  /* Фокус — заметный для клавиатуры */
  &:focus-visible {
    outline: 3px solid var(--color-primary);
    outline-offset: 2px;
    border-color: var(--color-primary);
  }

  /* Состояние ошибки */
  &[aria-invalid="true"] {
    border-color: var(--color-error);
  }

  &[aria-invalid="true"]:focus-visible {
    outline-color: var(--color-error);
  }
}

.c-form__hint {
  font-size: var(--fs-xs);
  color: var(--color-muted);
  margin-block-start: var(--space-xs);
}

.c-form__error {
  font-size: var(--fs-xs);
  color: var(--color-error);
  margin-block-start: var(--space-xs);
}

.c-form__radio {
  display: inline-flex;
  align-items: center;
  margin-inline-end: var(--space-md);
  cursor: pointer;
}

.c-form__radio input {
  margin-inline-end: var(--space-xs);
}

/* Показываем ошибку когда инпут невалидный и не в фокусе */
.c-form__field:has(input:invalid:not(:focus-visible)) .c-form__error {
  display: block;
}

/* Зеленая граница когда валидно */
.c-form__field:has(input:valid) .c-form__input {
  border-color: var(--color-success);
}

const toggle = document.querySelector('.c-nav__toggle');
const menu = document.querySelector('#nav-menu');

toggle.addEventListener('click', () => {
  const expanded = toggle.getAttribute('aria-expanded') === 'true';
  toggle.setAttribute('aria-expanded', !expanded);
  menu.hidden = !menu.hidden;

  if (!expanded) {
    // Переместить фокус в первое место навигации
    const firstLink = menu.querySelector('a');
    if (firstLink) firstLink.focus();
  }
});

// Закрытие по ESC
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && !menu.hidden) {
    toggle.setAttribute('aria-expanded', 'false');
    menu.hidden = true;
    toggle.focus();
  }
});

/* styles.css — доступные стили */
@layer base, components;

@layer base {
  :root {
    --color-bg: oklch(0.98 0.001 285);
    --color-text: oklch(0.21 0.006 285);
    --color-primary: oklch(0.62 0.22 264);
    --color-border: oklch(0.88 0.006 285);
    --space-xs: 0.25rem;
    --space-sm: 0.5rem;
    --space-md: 1rem;
    --space-lg: 1.5rem;
    --radius-md: 0.5rem;
    --fs-base: 1rem;
    --fs-lg: 1.25rem;
  }

  * {
    box-sizing: border-box;
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    font-family: system-ui, -apple-system, sans-serif;
    font-size: var(--fs-base);
    line-height: 1.6;
    color: var(--color-text);
    background: var(--color-bg);
    margin: 0;
  }

  /* Reduced motion */
  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
    }
  }

  /* RTL через data-атрибут */
  [dir="rtl"] {
    /* Логические свойства автоматически отзеркалятся */
  }
}

@layer components {
  .skip-link {
    position: absolute;
    top: -100px;
    left: 0;
    background: var(--color-primary);
    color: white;
    padding: var(--space-sm) var(--space-md);
    z-index: 1000;
    text-decoration: none;
    border-radius: 0 0 var(--radius-md) 0;
  }

  .skip-link:focus {
    top: 0;
  }

  .c-nav__list {
    display: flex;
    gap: var(--space-md);
    padding-inline-start: 0;
    margin: 0;
    list-style: none;
  }

  .c-nav__link {
    padding-inline-start: var(--space-sm);
    padding-inline-end: var(--space-sm);
    padding-block: 0.5rem;
    color: var(--color-text);
    text-decoration: none;
    border-radius: var(--radius-md);
    transition: background 0.2s;
  }

  .c-nav__link:focus-visible {
    outline: 3px solid var(--color-primary);
    outline-offset: 2px;
    background: color-mix(in oklch, var(--color-primary), white 90%);
  }

  .c-nav__link[aria-current="page"] {
    font-weight: 600;
    background: var(--color-primary);
    color: white;
  }

  .c-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    padding: var(--space-lg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    background: white;
    max-width: 400px;
    margin: var(--space-md);
  }

  .c-card__media {
    aspect-ratio: 16 / 9;
    width: 100%;
    background: oklch(0.97 0.001 285);
    border-radius: var(--radius-md);
    overflow: hidden;
    position: relative;
  }

  .c-card__img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  .c-card__badge {
    position: absolute;
    inset-block-start: var(--space-xs);
    inset-inline-start: var(--space-xs);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: var(--radius-md);
    background: var(--color-primary);
    color: white;
  }

  .c-card__body {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    flex: 1;
  }

  .c-card__title {
    font-size: var(--fs-lg);
    font-weight: 600;
    margin: 0;
    color: var(--color-text);
  }

  .c-card__text {
    font-size: var(--fs-base);
    color: oklch(0.45 0.01 285);
    margin: 0;
  }

  .c-card__price {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--color-text);
    margin-top: auto;
  }

  .c-card__footer {
    display: flex;
    gap: var(--space-sm);
    margin-top: auto;
  }

  .c-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    padding: var(--space-sm) var(--space-md);
    font-size: var(--fs-base);
    font-weight: 600;
    border: none;
    border-radius: var(--radius-md);
    cursor: pointer;
    min-height: 44px;
    transition: background 0.2s, transform 0.1s;
  }

  .c-btn--primary {
    background: var(--color-primary);
    color: white;
  }

  .c-btn--primary:hover {
    background: oklch(0.55 0.22 264);
  }

  .c-btn--primary:focus-visible {
    outline: 3px solid var(--color-primary);
    outline-offset: 3px;
    box-shadow: 0 0 0 4px color-mix(in oklch, var(--color-primary), white 50%);
  }

  .c-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
}
